-- Vector search (TiDB): HNSW indexes on embedding columns. TiFlash replicas are needed first.
ALTER TABLE `jobpostings` SET TIFLASH REPLICA 1;
ALTER TABLE `jobpostings__embeddings_responsibilities` SET TIFLASH REPLICA 1;
ALTER TABLE `resumeprofiles__embeddings_bullets` SET TIFLASH REPLICA 1;
ALTER TABLE `jobpostings` ADD VECTOR INDEX `vx_embeddings__title` ((VEC_COSINE_DISTANCE(`embeddings__title`))) USING HNSW;
ALTER TABLE `jobpostings__embeddings_responsibilities` ADD VECTOR INDEX `vx_vector` ((VEC_COSINE_DISTANCE(`vector`))) USING HNSW;
ALTER TABLE `resumeprofiles__embeddings_bullets` ADD VECTOR INDEX `vx_vector` ((VEC_COSINE_DISTANCE(`vector`))) USING HNSW;
